source='''from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    seen = set()
    objects = []

    for y in range(height):
        for x in range(width):
            if grid[y][x] == 0 or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            cells = []
            while stack:
                cy, cx = stack.pop()
                cells.append((cy, cx))
                for ny, nx in ((cy - 1, cx), (cy + 1, cx), (cy, cx - 1), (cy, cx + 1)):
                    if 0 <= ny < height and 0 <= nx < width and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            perimeter = [grid[y][x] for y, x in cells if y in (y0, y1) or x in (x0, x1)]
            frame = Counter(perimeter).most_common(1)[0][0]
            inner = {}
            for y, x in cells:
                color = grid[y][x]
                if color != frame:
                    inner.setdefault(color, set()).add((y, x))
            objects.append({"y0": y0, "y1": y1, "x0": x0, "x1": x1, "inner": inner})

    counts = Counter()
    for obj in objects:
        for color, coords in obj["inner"].items():
            counts[color] += len(coords)
    if not counts:
        return out
    background = counts.most_common(1)[0][0]

    for i, a in enumerate(objects):
        for b in objects[i + 1:]:
            for color in a["inner"].keys() & b["inner"].keys():
                if color == background:
                    continue
                if a["y0"] == b["y0"] and a["y1"] == b["y1"]:
                    left, right = (a, b) if a["x0"] < b["x0"] else (b, a)
                    if left["x1"] >= right["x0"]:
                        continue
                    rows = {y for y, x in left["inner"].get(color, set())} & {y for y, x in right["inner"].get(color, set())}
                    for y in rows:
                        for x in range(left["x1"] + 1, right["x0"]):
                            if out[y][x] == 0:
                                out[y][x] = color
                elif a["x0"] == b["x0"] and a["x1"] == b["x1"]:
                    top, bottom = (a, b) if a["y0"] < b["y0"] else (b, a)
                    if top["y1"] >= bottom["y0"]:
                        continue
                    cols = {x for y, x in top["inner"].get(color, set())} & {x for y, x in bottom["inner"].get(color, set())}
                    for x in cols:
                        for y in range(top["y1"] + 1, bottom["y0"]):
                            if out[y][x] == 0:
                                out[y][x] = color
    return out
